const http = require("http");
const { createClient } = require("@clickhouse/client");

const clickhouse = createClient({
  url: process.env.CLICKHOUSE_URL || "http://localhost:8123",
});

function buildQuery(params) {
  const conditions = [];
  const queryParams = {};

  if (params.date_from) {
    conditions.push("ts >= {date_from: DateTime}");
    queryParams.date_from = params.date_from + " 00:00:00";
  }
  if (params.date_to) {
    conditions.push("ts <= {date_to: DateTime}");
    queryParams.date_to = params.date_to + " 23:59:59";
  }
  if (params.region_id) {
    conditions.push("region_id = {region_id: UInt32}");
    queryParams.region_id = Number(params.region_id);
  }
  if (params.product_id) {
    conditions.push("product_id = {product_id: UInt32}");
    queryParams.product_id = Number(params.product_id);
  }

  const where = conditions.length ? "WHERE " + conditions.join(" AND ") : "";
  const sql = `SELECT sum(value) AS total_value, count() AS event_count FROM analytics.events ${where}`;
  return { sql, queryParams };
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, "http://localhost");

  if (req.method !== "GET" || url.pathname !== "/api/metrics") {
    res.writeHead(404);
    res.end(JSON.stringify({ error: "Not found" }));
    return;
  }

  const params = Object.fromEntries(url.searchParams);
  const { sql, queryParams } = buildQuery(params);

  try {
    const result = await clickhouse.query({
      query: sql,
      query_params: queryParams,
      format: "JSONEachRow",
    });
    const rows = await result.json();
    const row = rows[0] || { total_value: 0, event_count: 0 };

    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({
      total_value: Number(row.total_value),
      event_count: Number(row.event_count),
    }));
  } catch (err) {
    res.writeHead(500);
    res.end(JSON.stringify({ error: err.message }));
  }
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => console.log(`Metrics API listening on port ${PORT}`));

